function pick(obj, path) {
  return String(path).split('.').reduce((o, k) => (o == null ? undefined : o[k]), obj);
}
function num(...vals) {
  for (const v of vals) {
    if (v == null) continue;
    const n = typeof v === 'string' ? Number(v) : v;
    if (typeof n === 'number' && Number.isFinite(n)) return n;
  }
  return undefined;
}
function str(v) {
  return typeof v === 'string' ? v : v == null ? '' : String(v);
}
function deepFind(root, match, depth) {
  depth = depth || 0;
  if (root == null || depth > 6 || typeof root !== 'object') return undefined;
  if (!Array.isArray(root) && match(root)) return root;
  for (const v of Object.values(root)) {
    if (v && typeof v === 'object') {
      const f = deepFind(v, match, depth + 1);
      if (f) return f;
    }
  }
  return undefined;
}
function deepFindArray(root, match, depth) {
  depth = depth || 0;
  if (root == null || depth > 6 || typeof root !== 'object') return undefined;
  if (Array.isArray(root)) {
    if (root.length && root.some((el) => el && typeof el === 'object' && match(el))) return root;
  }
  for (const v of Object.values(root)) {
    if (v && typeof v === 'object') {
      const f = deepFindArray(v, match, depth + 1);
      if (f) return f;
    }
  }
  return undefined;
}
function unwrap(raw) {
  if (raw && typeof raw === 'object') {
    if (raw.node && typeof raw.node === 'object') return raw.node;
    if (raw.media && typeof raw.media === 'object') return raw.media;
  }
  return raw || {};
}
function isoFrom(ts) {
  const t = num(ts);
  if (t == null) return '';
  return new Date(t > 1e12 ? t : t * 1000).toISOString();
}

// Lead scoring and market filtering, exactly as the Scavio dashboard tool does it.
const query = str($('Loop searches').first().json.query).trim();

// Market tokens = everything after a standalone "in", lowercased and split.
// "plumbers in Austin, TX" -> ["austin", "tx"]
function marketTokens(q) {
  const m = q.match(/\bin\s+(.+)$/i);
  if (!m) return [];
  return m[1].split(/[, ]+/).map((s) => s.trim().toLowerCase()).filter((s) => s.length >= 2);
}
const tokens = marketTokens(query);

// A lead with no address is dropped when a market is specified -- same as the dashboard.
function inMarket(b) {
  if (tokens.length === 0) return true;
  const addr = str(b.address).toLowerCase();
  return !!addr && tokens.some((t) => addr.includes(t));
}

function scoreLead(b) {
  const reasons = [];
  let score = 0;
  const rating = num(b.rating);
  const reviews = num(b.reviews);
  if (!b.website) { score += 40; reasons.push('no website'); }
  if (rating != null && rating < 4.0) { score += 25; reasons.push('low rating (' + rating + ')'); }
  if (reviews != null && reviews < 20) { score += 20; reasons.push('few reviews (' + reviews + ')'); }
  if (!b.phone) { score += 15; reasons.push('no phone'); }
  return { score: score, reasons: reasons };
}

const pages = ['Maps page 1', 'Maps page 2', 'Maps page 3'];
const byKey = new Map();

for (const pageName of pages) {
  let raw;
  try { raw = $(pageName).first().json; } catch (e) { raw = undefined; }
  const list = (raw && raw.local_results) || pick(raw, 'data.local_results') || [];
  if (!Array.isArray(list) || list.length === 0) continue;
  for (const b of list) {
    if (!b || typeof b !== 'object') continue;
    // First occurrence wins, across all pages.
    const key = str(b.place_id) || str(b.data_id) || str(b.title);
    if (!key || byKey.has(key)) continue;
    if (!inMarket(b)) continue;
    const scored = scoreLead(b);
    byKey.set(key, {
      query: query,
      foundAt: new Date().toISOString().slice(0, 10),
      name: str(b.title),
      address: str(b.address),
      phone: str(b.phone),
      website: str(b.website),
      rating: num(b.rating) ?? '',
      reviews: num(b.reviews) ?? '',
      category: str(b.type),
      score: scored.score,
      opportunities: scored.reasons.join('; '),
      mapsUrl: b.place_id ? 'https://www.google.com/maps/place/?q=place_id:' + str(b.place_id) : '',
    });
  }
}

const leads = [...byKey.values()].sort((a, b) => b.score - a.score);

if (leads.length === 0) {
  return [];
}

return leads.map((l) => ({ json: l }));
